def semver_compare(a: str, b: str) -> int:
    def parse(v: str):
        # Remove build metadata as it is ignored in precedence
        main_part = v.split('+')[0]
        if '-' in main_part:
            base_str, pre_str = main_part.split('-', 1)
            pre = pre_str.split('.')
        else:
            base_str = main_part
            pre = None

        base = [int(x) for x in base_str.split('.')]
        return base, pre

    base_a, pre_a = parse(a)
    base_b, pre_b = parse(b)

    # 1. Compare Major, Minor, Patch
    if base_a < base_b:
        return -1
    if base_a > base_b:
        return 1

    # 2. Handle Prerelease presence (base version has higher precedence than prerelease)
    if pre_a is None and pre_b is None:
        return 0
    if pre_a is None:
        return 1
    if pre_b is None:
        return -1

    # 3. Compare Prerelease identifiers
    for p_a, p_b in zip(pre_a, pre_b):
        is_a_num = p_a.isdigit()
        is_b_num = p_b.isdigit()

        if is_a_num and is_b_num:
            n_a, n_b = int(p_a), int(p_b)
            if n_a < n_b: return -1
            if n_a > n_b: return 1
        elif not is_a_num and not is_b_num:
            if p_a < p_b: return -1
            if p_a > p_b: return 1
        else:
            # Numeric identifiers have lower precedence than non-numeric identifiers
            return -1 if is_a_num else 1

    # 4. A larger set of pre-release fields has higher precedence than a smaller set
    if len(pre_a) < len(pre_b):
        return -1
    if len(pre_a) > len(pre_b):
        return 1

    return 0
