def parse_csv_line(line: str) -> list[str]:
    fields = []
    current_field = ""
    i = 0
    n = len(line)

    while i < n:
        # A field that starts with a double quote is quoted
        if current_field == "" and line[i] == '"':
            i += 1  # Skip the opening quote
            while i < n:
                if line[i] == '"':
                    # Check for escaped quotes ("")
                    if i + 1 < n and line[i+1] == '"':
                        current_field += '"'
                        i += 2
                    else:
                        # Closing quote reached
                        i += 1
                        if i == n or line[i] == ',':
                            break
                        else:
                            raise ValueError("Closing quote followed by invalid character")
                else:
                    current_field += line[i]
                    i += 1
            else:
                # If the inner loop finished without a break, the quote was never closed
                raise ValueError("Quoted field never closed")
        elif line[i] == ',':
            # End of a field
            fields.append(current_field)
            current_field = ""
            i += 1
        else:
            # Regular character in an unquoted field
            current_field += line[i]
            i += 1

    # Append the final field remaining after the last comma or end of string
    fields.append(current_field)
    return fields
