def glob_match(pattern: str, s: str) -> bool:
    tokens = []
    i = 0
    while i < len(pattern):
        c = pattern[i]
        if c == '*':
            tokens.append(('STAR',))
            i += 1
        elif c == '?':
            tokens.append(('ANY',))
            i += 1
        elif c == '[':
            i += 1
            end = pattern.find(']', i)
            content = pattern[i:end]
            i = end + 1
            allowed = set()
            negate = False
            if content.startswith('!'):
                negate = True
                content = content[1:]

            j = 0
            while j < len(content):
                if j + 2 < len(content) and content[j+1] == '-':
                    start = ord(content[j])
                    end_char = ord(content[j+2])
                    for code in range(start, end_char + 1):
                        allowed.add(chr(code))
                    j += 3
                else:
                    allowed.add(content[j])
                    j += 1
            tokens.append(('SET', allowed, negate))
        else:
            tokens.append(('LIT', c))
            i += 1

    memo = {}

    def solve(p_idx, s_idx):
        if (p_idx, s_idx) in memo:
            return memo[(p_idx, s_idx)]

        if p_idx == len(tokens):
            return s_idx == len(s)

        token = tokens[p_idx]
        res = False

        if token[0] == 'STAR':
            # Option 1: * matches empty string
            if solve(p_idx + 1, s_idx):
                res = True
            # Option 2: * matches one character and we stay on *
            elif s_idx < len(s) and solve(p_idx, s_idx + 1):
                res = True
        elif token[0] == 'ANY':
            if s_idx < len(s) and solve(p_idx + 1, s_idx + 1):
                res = True
        elif token[0] == 'LIT':
            if s_idx < len(s) and s[s_idx] == token[1]:
                res = solve(p_idx + 1, s_idx + 1)
        elif token[0] == 'SET':
            allowed, negate = token[1], token[2]
            if s_idx < len(s):
                is_in = s[s_idx] in allowed
                if (negate and not is_in) or (not negate and is_in):
                    res = solve(p_idx + 1, s_idx + 1)

        memo[(p_idx, s_idx)] = res
        return res

    return solve(0, 0)
