            for i, chunk in enumerate(chunks):
                if i == len(chunks) - 1:
                    # The last piece of a long word acts like a normal word
                    if current_line and current_len + 1 + len(chunk) <= width:
                        current_line.append(chunk)
                        current_len += 1 + len(chunk)
