def glob_match(pattern: str, s: str) -> bool:
    atoms = []
    i = 0
    while i < len(pattern):
        char = pattern[i]
        if char == '*':
            atoms.append('*')
            i += 1
        elif char == '?':
            atoms.append('?')
            i += 1
        elif char == '[':
            i += 1
            negate = False
            if i < len(pattern) and pattern[i] == '!':
                negate = True
                i += 1

            allowed = set()
            while i < len(pattern) and pattern[i] != ']':
                if i + 2 < len(pattern) and pattern[i+1] == '-':
                    start = ord(pattern[i])
                    end = ord(pattern[i+2])
                    for code in range(start, end + 1):
                        allowed.add(chr(code))
                    i += 3
                else:
                    allowed.add(pattern[i])
                    i += 1
            i += 1 # skip ]
            atoms.append(('set', allowed, negate))
        else:
            atoms.append(char)
            i += 1

    n, m = len(atoms), len(s)
    dp = [[False] * (m + 1) for _ in range(n + 1)]
    dp[n][m] = True

    for i in range(n - 1, -1, -1):
        atom = atoms[i]
        for j in range(m, -1, -1):
            if atom == '*':
                dp[i][j] = dp[i+1][j]
                if j < m:
                    dp[i][j] = dp[i][j] or dp[i][j+1]
            elif atom == '?':
                if j < m:
                    dp[i][j] = dp[i+1][j+1]
            elif isinstance(atom, str):
                if j < m and s[j] == atom:
                    dp[i][j] = dp[i+1][j+1]
            elif atom[0] == 'set':
                allowed, negate = atom[1], atom[2]
                if j < m:
                    if (s[j] in allowed if not negate else s[j] not in allowed):
                        dp[i][j] = dp[i+1][j+1]

    return dp[0][0]
