def normalize_path(path: str) -> str:
    if not path:
        return '.'

    is_absolute = path.startswith('/')
    segments = path.split('/')
    stack = []

    for seg in segments:
        if seg == '' or seg == '.':
            continue
        if seg == '..':
            if stack and stack[-1] != '..':
                stack.pop()
            elif not is_absolute and not stack:
                stack.append('..')
        else:
            stack.append(seg)

    result = "/".join(stack)
    if is_absolute:
        return "/" + result
    return result if result else "."
