    if not line:
        return ['']

    fields = []
    i = 0
    n = len(line)

    while i < n:
        if line[i] == '"':
            # Quoted field
            i += 1  # Skip opening quote
            field = []
            closed = False
            while i < n:
                if line[i] == '"':
                    if i + 1 < n and line[i+1] == '"':
                        field.append('"')
                        i += 2
                    else:
                        # Closing quote
                        closed = True
                        i += 1
                        break
                else:
                    field.append(line[i])
                    i += 1

            if not closed:
                raise ValueError("Unclosed quoted field")

            # Check character after closing quote
            if i < n and line[i] != ',':
                raise ValueError("Closing quote followed by invalid character")

            fields.append("".join(field))

            # Move past the comma if it exists
            if i < n and line[i] == ',':
                i += 1
                if i == n:
                    fields.append('')
        else:
            # Unquoted field
            field = []
            while i < n and line[i] != ',':
                field.append(line[i])
                i += 1
            fields.append("".join(field))

            if i < n and line[i] == ',':
                i += 1
                if i == n:
                    fields.append('')

    return fields
