import heapq

def topo_sort(deps: dict[str, list[str]]) -> list[str]:
    # Identify all unique nodes in the graph
    all_nodes = set(deps.keys())
    for dependencies in deps.values():
        for dep in dependencies:
            all_nodes.add(dep)

    # Build adjacency list and calculate in-degrees
    # If node depends on dep, there is a directed edge: dep -> node
    adj = {node: [] for node in all_nodes}
    in_degree = {node: 0 for node in all_nodes}

    for node, dependencies in deps.items():
        for dep in dependencies:
            adj[dep].append(node)
            in_degree[node] += 1

    # Kahn's algorithm with a min-heap for alphabetical tie-breaking
    heap = [node for node in all_nodes if in_degree[node] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        u = heapq.heappop(heap)
        result.append(u)
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                heapq.heappush(heap, v)

    # If result doesn't contain all nodes, there's a cycle
    if len(result) != len(all_nodes):
        raise ValueError("Cycle detected")

    return result
