import heapq

def topo_sort(deps: dict[str, list[str]]) -> list[str]:
    # Identify all unique nodes including those only appearing as dependencies
    nodes = set(deps.keys())
    for d_list in deps.values():
        nodes.update(d_list)

    # adj[u] = list of nodes that depend on u
    # in_degree[v] = count of nodes that v depends on
    adj = {node: [] for node in nodes}
    in_degree = {node: 0 for node in nodes}

    for node, dependencies in deps.items():
        in_degree[node] = len(dependencies)
        for dep in dependencies:
            adj[dep].append(node)

    # Use a min-heap to ensure the alphabetically smallest node is taken first
    heap = [node for node in nodes if in_degree[node] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        u = heapq.heappop(heap)
        result.append(u)
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                heapq.heappush(heap, v)

    # If result length doesn't match total nodes, a cycle exists
    if len(result) != len(nodes):
        raise ValueError("Cycle detected")

    return result
