import re

def semver_compare(a: str, b: str) -> int:
    pattern = re.compile(
        r'^(\d+)\.(\d+)\.(\d+)(?:-([0-9A-Za-z.-]+))?(?:\+([0-9A-Za-z.-]+))?$'
    )
    ma, mb = pattern.match(a), pattern.match(b)
    if not ma or not mb:
        raise ValueError("invalid semantic version")
    for x, y in zip(ma.groups()[:3], mb.groups()[:3]):
        x, y = int(x), int(y)
        if x != y:
            return -1 if x < y else 1
    pre_a, pre_b = ma.group(4), mb.group(4)
    if pre_a is None and pre_b is None:
        return 0
    if pre_a is None:
        return 1
    if pre_b is None:
        return -1
    ids_a = pre_a.split('.')
    ids_b = pre_b.split('.')
    for x, y in zip(ids_a, ids_b):
        if x == y:
            continue
        num_x, num_y = x.isdigit(), y.isdigit()
        if num_x and num_y:
            return -1 if int(x) < int(y) else 1
        if num_x != num_y:
            return -1 if num_x else 1
        return -1 if x < y else 1
    if len(ids_a) == len(ids_b):
        return 0
    return -1 if len(ids_a) < len(ids_b) else 1
