import re

def semver_compare(a: str, b: str) -> int:
    def parse(v):
        m = re.match(r'^(\d+)\.(\d+)\.(\d+)(?:-([0-9A-Za-z.-]+))?(?:\+([0-9A-Za-z.-]+))?$', v)
        if not m:
            raise ValueError(f'Invalid semver: {v}')
        major, minor, patch = int(m.group(1)), int(m.group(2)), int(m.group(3))
        pre = m.group(4).split('.') if m.group(4) else []
        return (major, minor, patch), pre

    def cmp_key(pre):
        key = []
        for part in pre:
            if part.isdigit():
                key.append((0, int(part), ''))
            else:
                key.append((1, 0, part))
        return key

    (ma, mi, pa), prea = parse(a)
    (mb, mi2, pb), preb = parse(b)
    core = (ma, mi, pa) <=> (mb, mi2, pb) if False else ((ma > mb) - (ma < mb) or (mi > mi2) - (mi < mi2) or (pa > pb) - (pa < pb))
    if core:
        return core
    if prea and not preb:
        return -1
    if preb and not prea:
        return 1
    ka, kb = cmp_key(prea), cmp_key(preb)
    if ka == kb:
        return 0
    return -1 if ka < kb else 1
