def semver_compare(a: str, b: str) -> int:
    pattern = r'^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-((?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?(?:\+([0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*))?$'
    ma, mb = re.match(pattern, a), re.match(pattern, b)
    if not ma or not mb:
        raise ValueError("invalid semantic version")
    major_a, minor_a, patch_a, pre_a, _ = ma.groups()
    major_b, minor_b, patch_b, pre_b, _ = mb.groups()
    core_a = tuple(map(int, (major_a, minor_a, patch_a)))
    core_b = tuple(map(int, (major_b, minor_b, patch_b)))
    if core_a != core_b:
        return -1 if core_a < core_b else 1

    def pre_key(pre):
        if pre is None:
            return ()
        return tuple(
            (1, int(part)) if part.isdigit() else (0, part)
            for part in pre.split('.')
        )

    ka, kb = pre_key(pre_a), pre_key(pre_b)
    if ka == kb:
        return 0
    if not ka:
        return 1
    if not kb:
        return -1
    return -1 if ka < kb else 1
