def glob_match(pattern: str, s: str) -> bool:
    n, m = len(pattern), len(s)
    # dp[i][j]: pattern[i:] matches s[j:]
    dp = [[False] * (m + 1) for _ in range(n + 1)]
    dp[n][m] = True
    for i in range(n - 1, -1, -1):
        for j in range(m, -1, -1):
            c = pattern[i]
            if c == '*':
                dp[i][j] = dp[i + 1][j] or (j < m and dp[i][j + 1])
            elif j >= m:
                dp[i][j] = False
            elif c == '?':
                dp[i][j] = dp[i + 1][j + 1]
            elif c == '[':
                k = i + 1
                negate = False
                if k < n and pattern[k] in '!^':
                    negate = True
                    k += 1
                items = []
                closed = False
                while k < n:
                    if pattern[k] == ']' and k > i + 1 + (1 if negate else 0):
                        closed = True
                        break
                    if k + 2 < n and pattern[k + 1] == '-' and pattern[k + 2] != ']':
                        items.append((pattern[k], pattern[k + 2]))
                        k += 3
                    else:
                        items.append((pattern[k], pattern[k]))
                        k += 1
                if not closed:
                    # unterminated: treat '[' literally
                    dp[i][j] = (s[j] == '[') and dp[i + 1][j + 1]
                else:
                    matched = any(lo <= s[j] <= hi for lo, hi in items)
                    if negate:
                        matched = not matched
                    dp[i][j] = matched and dp[k + 1][j + 1]
            else:
                dp[i][j] = (s[j] == c) and dp[i + 1][j + 1]
    return dp[0][0]
```

