def eval_expr(s: str) -> int:
    tokens = []
    i = 0
    while i < len(s):
        c = s[i]
        if c.isspace():
            i += 1
        elif c.isdigit():
            j = i
            while j < len(s) and s[j].isdigit():
                j += 1
            tokens.append(int(s[i:j]))
            i = j
        else:
            tokens.append(c)
            i += 1

    pos = [0]

    def peek():
        return tokens[pos[0]] if pos[0] < len(tokens) else None

    def eat():
        t = tokens[pos[0]]
        pos[0] += 1
        return t

    def parse_expr():
        val = parse_term()
        while peek() in ('+', '-'):
            op = eat()
            rhs = parse_term()
            val = val + rhs if op == '+' else val - rhs
        return val

    def parse_term():
        val = parse_factor()
        while peek() in ('*', '/'):
            op = eat()
            rhs = parse_factor()
            if op == '*':
                val *= rhs
            else:
                val = int(val / rhs) if (val < 0) != (rhs < 0) else val // rhs
        return val

    def parse_factor():
        t = peek()
        if t == '-':
            eat()
            return -parse_factor()
        if t == '+':
            eat()
            return parse_factor()
        if t == '(':
            eat()
            val = parse_expr()
            eat()  # ')'
            return val
        return eat()

    return parse_expr()
```

