def eval_expr(s: str) -> int:
    def helper(i):
        (val, i) = parse_expr(i)
        return val, i

    def skip_ws(i):
        while i < len(s) and s[i] == ' ':
            i += 1
        return i

    def parse_expr(i):
        val, i = parse_term(i)
        while True:
            i = skip_ws(i)
            if i < len(s) and s[i] in '+-':
                op = s[i]
                rhs, i = parse_term(i + 1)
                val = val + rhs if op == '+' else val - rhs
            else:
                return val, i

    def parse_term(i):
        val, i = parse_factor(i)
        while True:
            i = skip_ws(i)
            if i < len(s) and s[i] in '*/':
                op = s[i]
                rhs, i = parse_factor(i + 1)
                if op == '*':
                    val *= rhs
                else:
                    q = abs(val) // abs(rhs)
                    val = q if (val < 0) == (rhs < 0) else -q
            else:
                return val, i

    def parse_factor(i):
        i = skip_ws(i)
        if s[i] == '(':
            val, i = parse_expr(i + 1)
            i = skip_ws(i)
            return val, i + 1  # skip ')'
        if s[i] == '-':
            val, i = parse_factor(i + 1)
            return -val, i
        if s[i] == '+':
            return parse_factor(i + 1)
        j = i
        while j < len(s) and s[j].isdigit():
            j += 1
        return int(s[i:j]), j

    return helper(0)[0]
