def glob_match(pattern: str, s: str) -> bool:
    from functools import lru_cache

    def parse_class(i):
        # i points at '['; returns (negated, chars_set, ranges, next_index)
        j = i + 1
        negated = False
        if j < len(pattern) and pattern[j] == '!':
            negated = True
            j += 1
        chars = set()
        ranges = []
        items = []
        first = True
        while j < len(pattern) and (pattern[j] != ']' or first):
            first = False
            if j + 2 < len(pattern) and pattern[j + 1] == '-' and pattern[j + 2] != ']':
                ranges.append((pattern[j], pattern[j + 2]))
                j += 3
            else:
                chars.add(pattern[j])
                j += 1
        return negated, chars, ranges, j + 1

    def class_match(negated, chars, ranges, c):
        ok = c in chars or any(lo <= c <= hi for lo, hi in ranges)
        return ok != negated

    @lru_cache(maxsize=None)
    def match(p, i):
        while True:
            if i == len(pattern):
                return p == len(s)
            c = pattern[i]
            if c == '*':
                # collapse consecutive stars
                while i + 1 < len(pattern) and pattern[i + 1] == '*':
                    i += 1
                for k in range(p, len(s) + 1):
                    if match(k, i + 1):
                        return True
                return False
            if p == len(s):
                return False
            if c == '?':
                p += 1
                i += 1
            elif c == '[':
                negated, chars, ranges, ni = parse_class(i)
                if not class_match(negated, chars, ranges, s[p]):
                    return False
                p += 1
                i = ni
            else:
                if s[p] != c:
                    return False
                p += 1
                i += 1

    return match(0, 0)
