def normalize_path(path: str) -> str:
    is_absolute = path.startswith('/')
    parts = path.split('/')
    stack = []
    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
            elif not is_absolute:
                stack.append('..')
            # at root of absolute path: drop
        else:
            stack.append(part)
    if is_absolute:
        return '/' + '/'.join(stack)
    if not stack:
        return '.'
    return '/'.join(stack)
