    def skip():
        nonlocal i
        while i < len(s) and s[i] == ' ':
            i += 1

    def expr():
        v = term()
        while True:
            skip()
            if i < len(s) and s[i] in '+-':
                op = s[i]
                nonlocal_i[0] += 1
                r = term()
                v = v + r if op == '+' else v - r
            else:
                return v

    def term():
        v = factor()
        while True:
            skip()
            if i < len(s) and s[i] in '*/':
                op = s[i]
                nonlocal_i[0] += 1
                r = factor()
                if op == '*':
                    v *= r
                else:
                    q = abs(v) // abs(r)
                    v = q if (v >= 0) == (r >= 0) else -q
            else:
                return v

    def factor():
        skip()
        if s[i] == '(':
            nonlocal_i[0] += 1
            v = expr()
            skip()
            nonlocal_i[0] += 1  # skip ')'
            return v
        if s[i] == '-':
            nonlocal_i[0] += 1
            return -factor()
        if s[i] == '+':
            nonlocal_i[0] += 1
            return factor()
        j = i
        while j < len(s) and s[j].isdigit():
            j += 1
        nonlocal_i[0] = j
        return int(s[i:j])

    nonlocal_i = [0]
    i = nonlocal_i[0]
    return expr()
