import re

def from_roman(s: str) -> int:
    values = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    pattern = re.compile(r'^M{0,3}(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})$')
    if not isinstance(s, str) or not pattern.fullmatch(s) or not s:
        raise ValueError(f"invalid Roman numeral: {s!r}")

    total = 0
    for i, ch in enumerate(s):
        v = values[ch]
        if i + 1 < len(s) and values[s[i + 1]] > v:
            total -= v
        else:
            total += v

    # canonical round-trip check (rejects e.g. 'VIV' or 'IL' style oddities)
    def to_roman(n):
        parts = [(1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'),
                 (100, 'C'), (90, 'XC'), (50, 'L'), (40, 'XL'),
                 (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'), (1, 'I')]
        result = []
        for val, sym in parts:
            while n >= val:
                result.append(sym)
                n -= val
        return ''.join(result)

    if to_roman(total) != s or not (1 <= total <= 3999):
        raise ValueError(f"invalid Roman numeral: {s!r}")
    return total
