from functools import lru_cache

def glob_match(pattern: str, s: str) -> bool:
    n, m = len(pattern), len(s)

    @lru_cache(maxsize=None)
    def match(p: int, i: int) -> bool:
        if p == n:
            return i == m
        c = pattern[p]
        if c == '*':
            return match(p + 1, i) or (i < m and match(p, i + 1))
        if i >= m:
            return False
        if c == '?':
            return match(p + 1, i + 1)
        if c == '[':
            j = p + 1
            neg = False
            if j < n and pattern[j] == '!':
                neg = True
                j += 1
            first = j
            in_set = False
            while j < n and (pattern[j] != ']' or j == first):
                if j + 2 < n and pattern[j + 1] == '-' and pattern[j + 2] != ']':
                    if pattern[j] <= s[i] <= pattern[j + 2]:
                        in_set = True
                    j += 3
                else:
                    if pattern[j] == s[i]:
                        in_set = True
                    j += 1
            if j >= n:
                # Unterminated '[': treat '[' literally
                return s[i] == '[' and match(p + 1, i + 1)
            j += 1  # skip ']'
            if in_set != neg:
                return match(j, i + 1)
            return False
        return match(p + 1, i + 1) if s[i] == c else False

    return match(0, 0)
