             for i, t in enumerate(thousands) if t
             for j, h in enumerate(hundreds) if h
             for k, te in enumerate(tens) if te
             for m, o in enumerate(ones) if o}
    # fix: simpler to build full map
    valid = {}
    for i, t in enumerate(thousands):
        for j, h in enumerate(hundreds):
            for k, te in enumerate(tens):
                for m, o in enumerate(ones):
                    if i + j + k + m > 0:
                        valid[t + h + te + o] = i * 1000 + j * 100 + k * 10 + m
    if s not in valid:
        raise ValueError(f'invalid Roman numeral: {s!r}')
    return valid[s]
