        raise ValueError('invalid Roman numeral')
    total = 0
    prev = 0
    for ch in reversed(s):
        if ch not in _VALUES:
            raise ValueError('invalid Roman numeral')
        value = _VALUES[ch]
        if value < prev:
            total -= value
        else:
            total += value
            prev = value
    if not (1 <= total <= 3999) or _to_roman(total) != s:
        raise ValueError('invalid Roman numeral')
    return total
