def normalize_path(path: str) -> str:
    absolute = path.startswith('/')
    parts = [p for p in path.split('/') if p and p != '.']
    stack = []
    depth = 0
    for part in parts:
        if part == '..':
            if stack:
                stack.pop()
            elif depth > 0:
                depth -= 1
            elif not absolute:
                depth += 1
        else:
            if depth > 0:
                stack.extend(['..'] * depth)
                depth = 0
            stack.append(part)
    if depth > 0:
        return '../' * depth + '/'.join(stack) if stack else '../' * depth
    if absolute:
        return '/' + '/'.join(stack) if stack else '/'
    return '/'.join(stack) if stack else '.'
