import heapq

def topo_sort(deps):
    nodes = set(deps)
    for ds in deps.values():
        nodes.update(ds)
    remaining = {n: set(deps.get(n, ())) & nodes for n in nodes}
    dependents = {n: set() for n in nodes}
    for n, ds in remaining.items():
        for d in ds:
            dependents[d].add(n)
    heap = sorted(n for n in nodes if not remaining[n])
    result = []
    while heap:
        n = heapq.heappop(heap)
        result.append(n)
        for m in dependents[n]:
            remaining[m].discard(n)
            if not remaining[m]:
                heapq.heappush(heap, m)
    if len(result) != len(nodes):
        raise ValueError("cycle detected")
    return result
