def parse_query(qs: str) -> dict[str, list[str]]:
    result: dict[str, list[str]] = {}

    def unescape(s: str) -> str:
        out = bytearray()
        i = 0
        while i < len(s):
            c = s[i]
            if c == '+':
                out.append(0x20)
                i += 1
            elif c == '%' and i + 2 < len(s) and all(ch in '0123456789abcdefABCDEF' for ch in s[i+1:i+3]):
                out.append(int(s[i+1:i+3], 16))
                i += 3
            else:
                out.extend(c.encode('utf-8'))
                i += 1
        return out.decode('utf-8', errors='replace')

    for pair in qs.split('&'):
        if not pair:
            continue
        if '=' in pair:
            key, value = pair.split('=', 1)
        else:
            key, value = pair, ''
        result.setdefault(unescape(key), []).append(unescape(value))
    return result
