        h, r = divmod(x, 100)
        return ones[h] + ' hundred' + (' ' + under_100(r) if r else '')

    if n == 0:
        return 'zero'
    th, rest = divmod(n, 1000)
    parts = []
    if th:
        parts.append(under_1000(th) + ' thousand')
    if rest:
        parts.append(under_1000(rest))
