def semver_compare(a: str, b: str) -> int:
    def parse(v: str):
        v = v.split('+', 1)[0]
        if '-' in v:
            main, pre = v.split('-', 1)
            pre = pre.split('.')
        else:
            main, pre = v, None
        main = [int(x) for x in main.split('.')]
        return main, pre

    ma, pa = parse(a)
    mb, pb = parse(b)

    for x, y in zip(ma, mb):
        if x < y:
            return -1
        if x > y:
            return 1

    if pa is None and pb is None:
        return 0
    if pa is None:
        return 1
    if pb is None:
        return -1

    for x, y in zip(pa, pb):
        x_num = x.isdigit()
        y_num = y.isdigit()

        if x_num and y_num:
            xi, yi = int(x), int(y)
            if xi < yi:
                return -1
            if xi > yi:
                return 1
        elif x_num and not y_num:
            return -1
        elif not x_num and y_num:
            return 1
        else:
            if x < y:
                return -1
            if x > y:
                return 1

    if len(pa) < len(pb):
        return -1
    if len(pa) > len(pb):
        return 1
    return 0
