import re

def semver_compare(a: str, b: str) -> int:
    pattern = (
        r'^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)'
        r'(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?'
        r'(?:\+[0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*)?$'
    )
    ma = re.match(pattern, a)
    mb = re.match(pattern, b)
    if not ma or not mb:
        raise ValueError("Invalid semantic version")

    av = tuple(map(int, ma.group(1, 2, 3)))
    bv = tuple(map(int, mb.group(1, 2, 3)))

    if av < bv:
        return -1
    if av > bv:
        return 1

    apr = ma.group(4)
    bpr = mb.group(4)

    if apr is None and bpr is None:
        return 0
    if apr is None:
        return 1
    if bpr is None:
        return -1

    aparts = apr.split('.')
    bparts = bpr.split('.')

    for ax, bx in zip(aparts, bparts):
        if ax == bx:
            continue

        a_num = ax.isdigit()
        b_num = bx.isdigit()

        if a_num and b_num:
            ai, bi = int(ax), int(bx)
            return -1 if ai < bi else 1
        if a_num:
            return -1
        if b_num:
            return 1
        return -1 if ax < bx else 1

    if len(aparts) < len(bparts):
        return -1
    if len(aparts) > len(bparts):
        return 1
    return 0
