        if num == 0:
            return ""
        elif num < 20:
            return ones[num]
        elif num < 100:
            t = tens[num // 10]
            o = num % 10
            return t + ("-" + ones[o] if o != 0 else "")
        else:
            h = num // 100
            r = num % 100
            res = ones[h] + " hundred"
            if r > 0:
                res += " " + convert_hundreds(r)
            return res

    thousands = n // 1000
    remainder = n % 1000

    parts = []
    if thousands > 0:
        parts.append(convert_hundreds(thousands) + " thousand")
    if remainder > 0:
        parts.append(convert_hundreds(remainder))

    return " ".join(parts).strip()
