def number_to_words(n: int) -> str:
    if n == 0:
        return "zero"

    units = ["", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine"]
    teens = ["ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen", "seventeen", "eighteen", "nineteen"]
    tens = ["", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"]

    def helper(num: int) -> str:
        if num == 0:
            return ""
        elif num < 10:
            return units[num]
        elif num < 20:
            return teens[num - 10]
        elif num < 100:
            res = tens[num // 10]
            if num % 10 != 0:
                res += "-" + units[num % 10]
            return res
        else:
            res = units[num // 100] + " hundred"
            rem = num % 100
            if rem != 0:
                res += " " + helper(rem)
            return res

    thousands = n // 1000
    remainder = n % 1000

    result = ""
    if thousands > 0:
        result = helper(thousands) + " thousand"

    if remainder > 0:
        if result != "":
            result += " " + helper(remainder)
        else:
            result = helper(remainder)

    return result
