def eval_expr(s: str) -> int:
    n = len(s)
    i = 0

    def skip():
        nonlocal i
        while i < n and s[i] == ' ':
            i += 1

    def trunc_div(a, b):
        q = abs(a) // abs(b)
        return q if (a >= 0) == (b >= 0) else -q

    def parse_expr():
        nonlocal i
        val = parse_term()
        while True:
            skip()
            if i < n and s[i] in '+-':
                op = s[i]
                i += 1
                rhs = parse_term()
                if op == '+':
                    val += rhs
                else:
                    val -= rhs
            else:
                break
        return val

    def parse_term():
        nonlocal i
        val = parse_factor()
        while True:
            skip()
            if i < n and s[i] in '*/':
                op = s[i]
                i += 1
                rhs = parse_factor()
                if op == '*':
                    val *= rhs
                else:
                    val = trunc_div(val, rhs)
            else:
                break
        return val

    def parse_factor():
        nonlocal i
        skip()
        if i < n and s[i] == '-':
            i += 1
            return -parse_factor()
        if i < n and s[i] == '(':
            i += 1
            val = parse_expr()
            skip()
            if i < n and s[i] == ')':
                i += 1
            return val
        start = i
        while i < n and s[i].isdigit():
            i += 1
        return int(s[start:i])

    return parse_expr()
