        nonlocal i
        val = parse_term()
        while True:
            skip()
            if i < n and s[i] in '+-':
                op = s[i]
                i += 1
                rhs = parse_term()
                if op == '+':
                    val += rhs
                else:
                    val -= rhs
            else:
                return val

    def parse_term():
        nonlocal i
        val = parse_factor()
        while True:
            skip()
            if i < n and s[i] in '*/':
                op = s[i]
                i += 1
                rhs = parse_factor()
                if op == '*':
                    val *= rhs
                else:
                    if rhs == 0:
                        raise ZeroDivisionError('division by zero')
                    q = abs(val) // abs(rhs)
                    if (val < 0) ^ (rhs < 0):
                        q = -q
                    val = q
            else:
                return val

    def parse_factor():
        nonlocal i
        skip()
        if i < n and s[i] in '+-':
            op = s[i]
            i += 1
            val = parse_factor()
            return val if op == '+' else -val
        return parse_primary()

    def parse_primary():
        nonlocal i
        skip()
        if i < n and s[i] == '(':
            i += 1
            val = parse_expr()
            skip()
            if i >= n or s[i] != ')':
                raise ValueError('missing closing parenthesis')
            i += 1
            return val

        start = i
        while i < n and s[i].isdigit():
            i += 1
        if start == i:
            raise ValueError('expected number')
        return int(s[start:i])

    skip()
    result = parse_expr()
    skip()
    if i != n:
        raise ValueError('unexpected character')
    return result
