def glob_match(pattern: str, s: str) -> bool:
    n, m = len(pattern), len(s)
    memo = {}

    def match(pi: int, si: int) -> bool:
        key = (pi, si)
        if key in memo:
            return memo[key]

        if pi == n:
            ans = si == m
        else:
            c = pattern[pi]

            if c == '*':
                ans = False
                for k in range(si, m + 1):
                    if match(pi + 1, k):
                        ans = True
                        break

            elif c == '?':
                ans = si < m and match(pi + 1, si + 1)

            elif c == '[':
                j = pi + 1
                neg = False
                if j < n and pattern[j] == '!':
                    neg = True
                    j += 1

                k = j
                while k < n and pattern[k] != ']':
                    k += 1

                if k == n:
                    ans = si < m and s[si] == '[' and match(pi + 1, si + 1)
                else:
                    content = pattern[j:k]
                    ans = False
                    if si < m:
                        ch = s[si]
                        matched = False
                        idx = 0
                        while idx < len(content):
                            if idx + 2 < len(content) and content[idx + 1] == '-':
                                start, end = content[idx], content[idx + 2]
                                if start <= ch <= end:
                                    matched = True
                                idx += 3
                            else:
                                if content[idx] == ch:
                                    matched = True
                                idx += 1

                        if neg:
                            matched = not matched
                        if matched:
                            ans = match(k + 1, si + 1)

            else:
                ans = si < m and s[si] == c and match(pi + 1, si + 1)

        memo[key] = ans
        return ans

    return match(0, 0)
