def glob_match(pattern: str, s: str) -> bool:
    tokens = []
    i = 0
    while i < len(pattern):
        c = pattern[i]
        if c == '*':
            tokens.append(('*',))
            i += 1
        elif c == '?':
            tokens.append(('?',))
            i += 1
        elif c == '[':
            j = i + 1
            neg = False
            if j < len(pattern) and pattern[j] == '!':
                neg = True
                j += 1
            items = []
            while j < len(pattern) and pattern[j] != ']':
                if j + 2 < len(pattern) and pattern[j + 1] == '-' and pattern[j + 2] != ']':
                    items.append(('range', pattern[j], pattern[j + 2]))
                    j += 3
                else:
                    items.append(('char', pattern[j]))
                    j += 1
            if j < len(pattern) and pattern[j] == ']':
                tokens.append(('class', neg, items))
                i = j + 1
            else:
                tokens.append(('lit', '['))
                i += 1
        else:
            tokens.append(('lit', c))
            i += 1

    def class_match(tok, ch):
        neg = tok[1]
        items = tok[2]
        ok = False
        for item in items:
            if item[0] == 'char':
                if ch == item[1]:
                    ok = True
                    break
            else:
                if item[1] <= ch <= item[2]:
                    ok = True
                    break
        return (not ok) if neg else ok

    dp = [False] * (len(s) + 1)
    dp[0] = True

    for tok in tokens:
        ndp = [False] * (len(s) + 1)
        if tok[0] == '*':
            acc = False
            for j in range(len(s) + 1):
                acc = acc or dp[j]
                ndp[j] = acc
        elif tok[0] == '?':
            for j in range(1, len(s) + 1):
                if dp[j - 1]:
                    ndp[j] = True
        elif tok[0] == 'lit':
            ch = tok[1]
            for j in range(1, len(s) + 1):
                if dp[j - 1] and s[j - 1] == ch:
                    ndp[j] = True
        elif tok[0] == 'class':
            for j in range(1, len(s) + 1):
                if dp[j - 1] and class_match(tok, s[j - 1]):
                    ndp[j] = True
        dp = ndp

    return dp[len(s)]
