    def skip_spaces():
        nonlocal i
        while i < n and s[i].isspace():
            i += 1

    def trunc_div(a, b):
        q = abs(a) // abs(b)
        return q if (a >= 0) == (b >= 0) else -q

    def parse_expr():
        nonlocal i
        val = parse_term()
        while True:
            skip_spaces()
            if i < n and s[i] in '+-':
                op = s[i]
                i += 1
                rhs = parse_term()
                if op == '+':
                    val += rhs
                else:
                    val -= rhs
            else:
                break
        return val

    def parse_term():
        nonlocal i
        val = parse_factor()
        while True:
            skip_spaces()
            if i < n and s[i] in '*/':
                op = s[i]
                i += 1
                rhs = parse_factor()
                if op == '*':
                    val *= rhs
                else:
                    val = trunc_div(val, rhs)
            else:
                break
        return val

    def parse_factor():
        nonlocal i
        skip_spaces()
        if i >= n:
            raise ValueError("unexpected end of expression")

        ch = s[i]
        if ch == '-':
            i += 1
            return -parse_factor()
        if ch == '+':
            i += 1
            return parse_factor()
        if ch == '(':
            i += 1
            val = parse_expr()
            skip_spaces()
            if i >= n or s[i] != ')':
                raise ValueError("missing closing parenthesis")
            i += 1
            return val
        if ch.isdigit():
            start = i
            while i < n and s[i].isdigit():
                i += 1
            return int(s[start:i])

        raise ValueError("invalid character")

    skip_spaces()
    result = parse_expr()
    skip_spaces()
    if i != n:
        raise ValueError("unexpected trailing characters")
    return result
