from functools import lru_cache

def glob_match(pattern: str, s: str) -> bool:
    def in_class(content: str, ch: str) -> bool:
        i = 0
        while i < len(content):
            if i + 2 < len(content) and content[i + 1] == '-':
                if content[i] <= ch <= content[i + 2]:
                    return True
                i += 3
            else:
                if content[i] == ch:
                    return True
                i += 1
        return False

    @lru_cache(None)
    def match(i: int, j: int) -> bool:
        if i == len(pattern):
            return j == len(s)

        c = pattern[i]

        if c == '*':
            return match(i + 1, j) or (j < len(s) and match(i, j + 1))

        if c == '?':
            return j < len(s) and match(i + 1, j + 1)

        if c == '[':
            k = i + 1
            neg = False

            if k < len(pattern) and pattern[k] == '!':
                neg = True
                k += 1

            start = k

            if k < len(pattern) and pattern[k] == ']':
                k += 1

            close = pattern.find(']', k)

            if close == -1:
                return j < len(s) and s[j] == '[' and match(i + 1, j + 1)

            content = pattern[start:close]

            if j >= len(s):
                return False

            ok = in_class(content, s[j])
            if neg:
                ok = not ok

            return ok and match(close + 1, j + 1)

        return j < len(s) and s[j] == c and match(i + 1, j + 1)

    return match(0, 0)
