def format_duration(seconds: int) -> str:
    if seconds == 0:
        return "now"

    units = [
        ("year", 365 * 24 * 60 * 60),
        ("day", 24 * 60 * 60),
        ("hour", 60 * 60),
        ("minute", 60),
        ("second", 1),
    ]

    parts = []
    for name, duration in units:
        value, seconds = divmod(seconds, duration)
        if value:
            parts.append(f"{value} {name}" if value == 1 else f"{value} {name}s")

    if len(parts) == 1:
        return parts[0]

    return ", ".join(parts[:-1]) + " and " + parts[-1]
