def from_roman(s: str) -> int:
    if not isinstance(s, str) or not s:
        raise ValueError("invalid Roman numeral")

    values = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50,
        'C': 100, 'D': 500, 'M': 1000
    }

    total = 0
    for i, ch in enumerate(s):
        if ch not in values:
            raise ValueError("invalid Roman numeral")
        v = values[ch]
        if i + 1 < len(s) and values.get(s[i + 1], 0) > v:
            total -= v
        else:
            total += v

    if not 1 <= total <= 3999:
        raise ValueError("invalid Roman numeral")

    pairs = [
        (1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'),
        (100, 'C'), (90, 'XC'), (50, 'L'), (40, 'XL'),
        (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'), (1, 'I')
    ]

    x = total
    parts = []
    for value, symbol in pairs:
        while x >= value:
            parts.append(symbol)
            x -= value

    if ''.join(parts) != s:
        raise ValueError("invalid Roman numeral")

    return total
