def number_to_words(n: int) -> str:
    if n == 0:
        return 'zero'

    ones = [
        '', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine',
        'ten', 'eleven', 'twelve', 'thirteen', 'fourteen', 'fifteen',
        'sixteen', 'seventeen', 'eighteen', 'nineteen'
    ]
    tens = [
        '', '', 'twenty', 'thirty', 'forty', 'fifty',
        'sixty', 'seventy', 'eighty', 'ninety'
    ]

    def under_1000(x: int) -> str:
        if x == 0:
            return ''
        if x < 20:
            return ones[x]
        if x < 100:
            if x % 10 == 0:
                return tens[x // 10]
            return tens[x // 10] + '-' + ones[x % 10]

        h = x // 100
        r = x % 100
        result = ones[h] + ' hundred'
        if r:
            result += ' ' + under_1000(r)
        return result

    if n < 1000:
        return under_1000(n)

    thousands = n // 1000
    remainder = n % 1000
    result = under_1000(thousands) + ' thousand'
    if remainder:
        result += ' ' + under_1000(remainder)
    return result
