import re
from typing import List, Tuple

_semver_regex = re.compile(
    r"""
    ^(?P<major>0|[1-9]\d*)\.
    (?P<minor>0|[1-9]\d*)\.
    (?P<patch>0|[1-9]\d*)
    (?:-(?P<prerelease>(?:[0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*)))?
    (?:\+(?P<build>(?:[0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*)))?
    $""",
    re.VERBOSE,
)

def _parse(version: str) -> Tuple[int, int, int, List[str], List[str]]:
    m = _semver_regex.fullmatch(version)
    if not m:
        raise ValueError(f"Invalid semantic version: {version!r}")
    major = int(m.group("major"))
    minor = int(m.group("minor"))
    patch = int(m.group("patch"))
    prerelease = m.group("prerelease")
    prerelease_parts = prerelease.split(".") if prerelease else []
    build = m.group("build")
    build_parts = build.split(".") if build else []
    return major, minor, patch, prerelease_parts, build_parts

def _compare_identifiers(a: str, b: str) -> int:
    a_is_num = a.isdigit()
    b_is_num = b.isdigit()
    if a_is_num and b_is_num:
        a_int = int(a)
        b_int = int(b)
        return (a_int > b_int) - (a_int < b_int)
    if a_is_num:
        return -1
    if b_is_num:
        return 1
    return (a > b) - (a < b)

def _compare_prerelease(a: List[str], b: List[str]) -> int:
    # No prerelease => higher precedence
    if not a and not b:
        return 0
    if not a:
        return 1
    if not b:
        return -1
    # Compare each dot-separated identifier
    for ai, bi in zip(a, b):
        cmp = _compare_identifiers(ai, bi)
        if cmp != 0:
            return cmp
    # If all equal so far, longer list wins
    return (len(a) > len(b)) - (len(a) < len(b))

def semver_compare(a: str, b: str) -> int:
    """Return -1 if a < b, 0 if a == b, 1 if a > b according to SemVer 2.0.0."""
    major_a, minor_a, patch_a, pre_a, _ = _parse(a)
    major_b, minor_b, patch_b, pre_b, _ = _parse(b)

    if major_a != major_b:
        return (major_a > major_b) - (major_a < major_b)
    if minor_a != minor_b:
        return (minor_a > minor_b) - (minor_a < minor_b)
    if patch_a != patch_b:
        return (patch_a > patch_b) - (patch_a < patch_b)

    return _compare_prerelease(pre_a, pre_b)
```

