import re
from functools import total_ordering

_semver_regex = re.compile(
    r"""
    ^(?P<major>0|[1-9]\d*)
    \.(?P<minor>0|[1-9]\d*)
    \.(?P<patch>0|[1-9]\d*)
    (?:-(?P<prerelease>(?:[0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*)))?
    (?:\+(?P<buildmetadata>[0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?
    $
    """,
    re.VERBOSE,
)

def _parse_semver(v: str):
    m = _semver_regex.match(v)
    if not m:
        raise ValueError(f"Invalid semantic version: {v!r}")
    major = int(m.group('major'))
    minor = int(m.group('minor'))
    patch = int(m.group('patch'))
    prerelease = m.group('prerelease')
    if prerelease is None:
        prerelease = ()
    else:
        prerelease = tuple(_parse_prerelease_id(x) for x in prerelease.split('.'))
    # build metadata is ignored for precedence
    return (major, minor, patch, prerelease)

def _parse_prerelease_id(id_str: str):
    # numeric identifiers are compared numerically, otherwise lexically
    if id_str.isdigit():
        # leading zeros are not allowed in numeric identifiers per spec,
        # but we treat them as numeric regardless
        return int(id_str)
    return id_str

@total_ordering
class _SemVer:
    __slots__ = ("_data",)
    def __init__(self, v: str):
        self._data = _parse_semver(v)

    def __eq__(self, other):
        if not isinstance(other, _SemVer):
            return NotImplemented
        return self._data == other._data

    def __lt__(self, other):
        if not isinstance(other, _SemVer):
            return NotImplemented
        a_major, a_minor, a_patch, a_pre = self._data
        b_major, b_minor, b_patch, b_pre = other._data

        if a_major != b_major:
            return a_major < b_major
        if a_minor != b_minor:
            return a_minor < b_minor
        if a_patch != b_patch:
            return a_patch < b_patch

        # At this point major/minor/patch are equal.
        # A version without a prerelease has higher precedence than one with.
        if not a_pre and b_pre:
            return False
        if a_pre and not b_pre:
            return True
        if not a_pre and not b_pre:
            return False  # equal

        # Both have prerelease identifiers; compare them sequentially.
        for a_id, b_id in zip(a_pre, b_pre):
            if a_id == b_id:
                continue
            # numeric identifiers have lower precedence than alphanumeric
            a_is_num = isinstance(a_id, int)
            b_is_num = isinstance(b_id, int)
            if a_is_num and not b_is_num:
                return True
            if not a_is_num and b_is_num:
                return False
            # both numeric or both string -> compare directly
            return a_id < b_id
        # All matched so far; shorter prerelease list wins
        return len(a_pre) < len(b_pre)

def semver_compare(a: str, b: str) -> int:
    """Return -1 if a < b, 0 if a == b, 1 if a > b according to SemVer 2.0.0."""
    av = _SemVer(a)
    bv = _SemVer(b)
    if av < bv:
        return -1
    if av > bv:
        return 1
    return 0
```

