from functools import lru_cache
from typing import Tuple

def glob_match(pattern: str, s: str) -> bool:
    def parse_char_class(p: str, i: int) -> Tuple[set, bool, int]:
        """Parse a character class starting at p[i]=='['.
        Returns (set_of_chars, negated, new_index_after_']')
        """
        i += 1
        neg = False
        if i < len(p) and p[i] in ('!', '^'):
            neg = True
            i += 1
        chars = set()
        while i < len(p) and p[i] != ']':
            if i + 2 < len(p) and p[i+1] == '-':
                start, end = p[i], p[i+2]
                for c in range(ord(start), ord(end) + 1):
                    chars.add(chr(c))
                i += 3
            else:
                chars.add(p[i])
                i += 1
        # skip closing ']'
        i += 1 if i < len(p) and p[i-1] == ']' else 0
        return chars, neg, i

    @lru_cache(None)
    def match(pi: int, si: int) -> bool:
        if pi == len(pattern):
            return si == len(s)
        if pattern[pi] == '*':
            # * matches zero or more characters
            # try all possibilities
            # zero chars
            if match(pi + 1, si):
                return True
            # one or more chars
            if si < len(s) and match(pi, si + 1):
                return True
            return False
        if si == len(s):
            # pattern left but string exhausted (except for possible trailing '*')
            return False

        c = pattern[pi]

        if c == '?':
            return match(pi + 1, si + 1)

        if c == '[':
            chars, neg, new_pi = parse_char_class(pattern, pi)
            if (s[si] in chars) ^ neg:
                return match(new_pi, si + 1)
            else:
                return False

        # literal character
        if c == s[si]:
            return match(pi + 1, si + 1)
        return False

    return match(0, 0)
