def glob_match(pattern: str, s: str) -> bool:
    from functools import lru_cache

    def parse_set(p, i):
        """Return (set_func, new_i) where set_func(ch) is True if ch matches the set."""
        negate = False
        if i < len(p) and p[i] == '!':
            negate = True
            i += 1
        chars = set()
        ranges = []
        while i < len(p) and p[i] != ']':
            if i + 2 < len(p) and p[i+1] == '-':
                # range a-z
                start, end = p[i], p[i+2]
                ranges.append((start, end))
                i += 3
            else:
                chars.add(p[i])
                i += 1
        i += 1  # skip closing ]

        def matcher(ch):
            ok = ch in chars or any(start <= ch <= end for start, end in ranges)
            return not ok if negate else ok

        return matcher, i

    @lru_cache(None)
    def dp(p_i: int, s_i: int) -> bool:
        if p_i == len(pattern):
            return s_i == len(s)
        if pattern[p_i] == '*':
            # * matches zero or more chars
            # try zero
            if dp(p_i + 1, s_i):
                return True
            # try to consume one char if possible
            if s_i < len(s) and dp(p_i, s_i + 1):
                return True
            return False
        if s_i >= len(s):
            return False

        pc = pattern[p_i]
        if pc == '?':
            return dp(p_i + 1, s_i + 1)
        if pc == '[':
            matcher, new_i = parse_set(pattern, p_i + 1)
            if matcher(s[s_i]):
                return dp(new_i, s_i + 1)
            return False
        # literal character
        if pc == s[s_i]:
            return dp(p_i + 1, s_i + 1)
        return False

    return dp(0, 0)
