        Returns a tuple (match_func, new_i) where match_func(ch) -> bool
        and new_i is the index after the closing ']'.
        """
        i += 1  # skip '['
        neg = False
        if i < len(p) and p[i] == '!':
            neg = True
            i += 1
        chars = set()
        ranges = []
        while i < len(p) and p[i] != ']':
            if i + 2 < len(p) and p[i + 1] == '-':
