                start, end = p[i], p[i + 2]
                ranges.append((start, end))
                i += 3
            else:
                chars.add(p[i])
                i += 1
        # skip the closing ']'
        i += 1

        def matcher(ch: str) -> bool:
            in_set = ch in chars or any(start <= ch <= end for start, end in ranges)
            return not in_set if neg else in_set

        return matcher, i

    @lru_cache(None)
    def dp(pi: int, si: int) -> bool:
        if pi == len(pattern):
            return si == len(s)
        if pi < len(pattern) and pattern[pi] == '*':
            # * matches empty or any char followed by *
            # try to consume zero chars
            if dp(pi + 1, si):
                return True
            # try to consume one char and stay on *
            if si < len(s) and dp(pi, si + 1):
                return True
            return False
        if si >= len(s):
            return False

        if pattern[pi] == '?':
            return dp(pi + 1, si + 1)

        if pattern[pi] == '[':
            matcher, new_pi = parse_set(pattern, pi)
            if matcher(s[si]):
                return dp(new_pi, si + 1)
            else:
                return False

        # literal character
        if pattern[pi] == s[si]:
            return dp(pi + 1, si + 1)
        return False

    return dp(0, 0)
