import re
from typing import List

def eval_expr(s: str) -> int:
    tokens = re.findall(r'\d+|[()+\-*/]', s.replace(' ', ''))
    pos = 0

    def peek() -> str:
        return tokens[pos] if pos < len(tokens) else ''

    def consume(expected: str = None) -> str:
        nonlocal pos
        if pos >= len(tokens):
            raise SyntaxError('Unexpected end of input')
        tok = tokens[pos]
        if expected and tok != expected:
            raise SyntaxError(f'Expected {expected!r}, got {tok!r}')
        pos += 1
        return tok

    def parse_expression() -> int:
        # handles + and -
        value = parse_term()
        while True:
            op = peek()
            if op == '+' or op == '-':
                consume()
                right = parse_term()
                if op == '+':
                    value += right
                else:
                    value -= right
            else:
                break
        return value

    def parse_term() -> int:
        # handles * and /
        value = parse_factor()
        while True:
            op = peek()
            if op == '*' or op == '/':
                consume()
                right = parse_factor()
                if op == '*':
                    value *= right
                else:
                    # truncates toward zero
                    value = int(value / right)
            else:
                break
        return value

    def parse_factor() -> int:
        # handles unary plus/minus and parentheses
        op = peek()
        if op == '+' or op == '-':
            consume()
            val = parse_factor()
            return val if op == '+' else -val
        if op == '(':
            consume('(')
            val = parse_expression()
            consume(')')
            return val
        # number
        return int(consume())

    result = parse_expression()
    if pos != len(tokens):
        raise SyntaxError('Unexpected token')
    return result
