def normalize_path(path: str) -> str:
    if not path:
        return '.'

    is_abs = path.startswith('/')
    parts = path.split('/')
    stack = []

    for part in parts:
        if part == '' or part == '.':
            # skip empty (from //) and current directory
            continue
        if part == '..':
            if stack:
                # pop only if there is a segment to go back from
                if stack[-1] != '..':
                    stack.pop()
                else:
                    # previous is also '..' -> keep this one as well
                    stack.append('..')
            else:
                # nothing to pop
                if not is_abs:
                    stack.append('..')
                # if absolute, ignore leading .. (cannot go above root)
            continue
        # normal component
        stack.append(part)

    if is_abs:
        result = '/' + '/'.join(stack)
        return result if result != '/' else '/'
    else:
        if not stack:
            return '.'
        return '/'.join(stack)
