import re
from typing import List

def eval_expr(s: str) -> int:
    tokens = re.findall(r'\d+|[+\-*/()]', s.replace(' ', ''))
    pos = 0

    def peek():
        return tokens[pos] if pos < len(tokens) else None

    def get():
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    def parse_factor() -> int:
        tok = peek()
        if tok == '+':
            get()
            return parse_factor()
        if tok == '-':
            get()
            return -parse_factor()
        if tok == '(':
            get()
            val = parse_expr()
            if peek() == ')':
                get()
            return val
        # number
        return int(get())

    def parse_term() -> int:
        val = parse_factor()
        while True:
            tok = peek()
            if tok == '*':
                get()
                val = val * parse_factor()
            elif tok == '/':
                get()
                divisor = parse_factor()
                # truncate toward zero
                val = int(val / divisor)
            else:
                break
        return val

    def parse_expr() -> int:
        val = parse_term()
        while True:
            tok = peek()
            if tok == '+':
                get()
                val = val + parse_term()
            elif tok == '-':
                get()
                val = val - parse_term()
            else:
                break
        return val

    result = parse_expr()
    return result
