def topo_sort(deps: dict[str, list[str]]) -> list[str]:
    # Build full set of nodes
    nodes = set(deps) | {v for vs in deps.values() for v in vs}
    # Initialize adjacency and indegree maps
    indeg: dict[str, int] = {n: 0 for n in nodes}
    adj: dict[str, list[str]] = {n: [] for n in nodes}
    for node, reqs in deps.items():
        for r in reqs:
            adj[r].append(node)
            indeg[node] += 1
    # Use a sorted list as a priority queue for nodes with indegree 0
    ready = sorted([n for n, d in indeg.items() if d == 0])
    result: list[str] = []
    while ready:
        cur = ready.pop(0)          # smallest alphabetically
        result.append(cur)
        for nxt in adj[cur]:
            indeg[nxt] -= 1
            if indeg[nxt] == 0:
                # Insert while keeping list sorted
                # binary insertion is fine for small sizes
                lo, hi = 0, len(ready)
                while lo < hi:
                    mid = (lo + hi) // 2
                    if ready[mid] < nxt:
                        lo = mid + 1
                    else:
                        hi = mid
                ready.insert(lo, nxt)
    if len(result) != len(nodes):
        raise ValueError("dependency cycle detected")
    return result
