def topo_sort(deps: dict[str, list[str]]) -> list[str]:
    # Build the full set of nodes
    nodes = set(deps) | {v for vals in deps.values() for v in vals}
    # Initialize adjacency and indegree
    indegree: dict[str, int] = {n: 0 for n in nodes}
    adj: dict[str, set[str]] = {n: set() for n in nodes}
    for node, dlist in deps.items():
        for dep in dlist:
            adj[dep].add(node)
            indegree[node] += 1
    # Use a sorted list as a priority queue for ready nodes
    ready = sorted([n for n, deg in indegree.items() if deg == 0])
    result: list[str] = []
    while ready:
        cur = ready.pop(0)                 # smallest alphabetical ready node
        result.append(cur)
        for nxt in sorted(adj[cur]):       # deterministic iteration
            indegree[nxt] -= 1
            if indegree[nxt] == 0:
                # insert while keeping list sorted
                # binary insertion could be used, but simple insert+sort is fine for modest sizes
                ready.append(nxt)
        ready.sort()
    if len(result) != len(nodes):
        raise ValueError("Cycle detected in dependencies")
    return result
