import urllib.parse
from collections import defaultdict

def parse_query(qs: str) -> dict[str, list[str]]:
    result: dict[str, list[str]] = {}
    if not qs:
        return result

    groups = qs.split('&')
    for group in groups:
        if not group:
            continue
        if '=' in group:
            key, value = group.split('=', 1)
        else:
            key, value = group, ''
        # Decode '+' as space and %XX as UTF-8
        key = urllib.parse.unquote_plus(key, encoding='utf-8', errors='strict')
        value = urllib.parse.unquote_plus(value, encoding='utf-8', errors='strict')
        if key in result:
            result[key].append(value)
        else:
            result[key] = [value]
    return result
