def number_to_words(n: int) -> str:
    if not (0 <= n <= 999_999):
        raise ValueError("n must be between 0 and 999999 inclusive")

    ones = [
        "zero", "one", "two", "three", "four", "five",
        "six", "seven", "eight", "nine"
    ]
    teens = [
        "ten", "eleven", "twelve", "thirteen", "fourteen",
        "fifteen", "sixteen", "seventeen", "eighteen", "nineteen"
    ]
    tens = [
        "", "", "twenty", "thirty", "forty", "fifty",
        "sixty", "seventy", "eighty", "ninety"
    ]

    def under_thousand(num: int) -> str:
        parts = []
        hundreds = num // 100
        remainder = num % 100

        if hundreds:
            parts.append(ones[hundreds] + " hundred")
        if remainder:
            if remainder < 10:
                parts.append(ones[remainder])
            elif remainder < 20:
                parts.append(teens[remainder - 10])
            else:
                ten_val = remainder // 10
                one_val = remainder % 10
                if one_val:
                    parts.append(f"{tens[ten_val]}-{ones[one_val]}")
                else:
                    parts.append(tens[ten_val])
        return " ".join(parts) if parts else ""

    # Special case zero
    if n == 0:
        return "zero"

    thousands = n // 1000
    remainder = n % 1000

    result_parts = []
    if thousands:
        result_parts.append(under_thousand(thousands) + " thousand")
    if remainder or not result_parts:
        # if remainder is 0 but we already have thousands, we skip adding anything
        # else we need to add the under‑thousand representation (including zero case handled above)
        remainder_word = under_thousand(remainder)
        if remainder_word:
            result_parts.append(remainder_word)

    return " ".join(result_parts)
