def number_to_words(n: int) -> str:
    if n == 0:
        return "zero"

    units = ["zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine"]
    teens = ["ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen", "seventeen", "eighteen", "nineteen"]
    tens = ["", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"]

    def convert_under_1000(num: int) -> str:
        if num == 0:
            return ""

        res = ""
        hundreds = num // 100
        remainder = num % 100

        if hundreds > 0:
            res += units[hundreds] + " hundred"
            if remainder > 0:
                res += " " + convert_under_1000(remainder)
        elif 10 <= remainder < 20:
            res += teens[remainder - 10]
        else:
            tens_digit = remainder // 10
            units_digit = remainder % 10
            if tens_digit > 0:
                res += tens[tens_digit]
                if units_digit > 0:
                    res += "-" + units[units_digit]
            else:
                res += units[units_digit]
        return res

    thousands_part = n // 1000
    remainder_part = n % 1000

    result = ""
    if thousands_part > 0:
        result = convert_under_1000(thousands_part) + " thousand"

    if remainder_part > 0:
        if result:
            result += " "
        result += convert_under_1000(remainder_part)

    return result
